/**
 * Bun's full garbage collection, as the `GarbageCollector` that
 * `@smthrs/sandbox`'s Microsandbox provider gives finished command handles
 * back to the guest with.
 *
 * Bun takes no V8 flags; it exposes its collector itself as `Bun.gc`.
 *
 * @since 1.0.0
 */
import * as Effect from "effect/Effect";
import { MicrosandboxSandbox } from "@smthrs/sandbox";
import * as Layer from "effect/Layer";
/**
 * The process's collector: `Bun.gc(true)`, which collects synchronously. It
 * is one value, so every Microsandbox provider in the process counts its
 * command starts toward the same collections.
 *
 * @category constructors
 * @since 1.0.0
 */
export const collector = {
    collect: Effect.sync({ collect: () => Bun.gc(true) }.collect),
};
/**
 * Provides {@link collector}.
 *
 * @category layers
 * @since 1.0.0
 */
export const layer = Layer.succeed(MicrosandboxSandbox.GarbageCollector)(collector);
